import { CONTENT as C } from './content.js';
import { DAY, STORAGE_KEY, freshState, localDay, dueCards, buildQueue, shuffled, checkAnswer, planReview, applyGrade, validateState } from './engine.js';
const $=s=>document.querySelector(s), app=$('#app'), dialog=$('#settings');
const cardById=Object.fromEntries(C.cards.map(c=>[c.id,c]));
const patternById=Object.fromEntries(C.patterns.map(p=>[p.id,p]));
const lessonById=Object.fromEntries(C.lessons.map(l=>[l.id,l]));
const e=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const icons={today:'<circle cx="12" cy="12" r="8.5"/><path d="M12 6v6l4 2"/>',map:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',practice:'<path d="m9 5 10 7-10 7Z"/><path d="M4 5v14"/>',mistakes:'<path d="M5 7a8 8 0 1 1-1 8M5 3v5h5"/>',audio:'<path d="m11 5-5 4H3v6h3l5 4V5Z"/><path d="M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="#1a1b1d"/><circle cx="15" cy="17" r="3" fill="#1a1b1d"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',back:'<path d="m14 5-7 7 7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1ZM12 5v15"/>',talk:'<path d="M21 11a8 8 0 0 1-8 8H8l-5 3V6a4 4 0 0 1 4-4h6a8 8 0 0 1 8 9Z"/><path d="M7 8h9M7 12h6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.book}</svg>`;
let storageOk=true, state;
try {const stored=localStorage.getItem(STORAGE_KEY);state=stored?validateState(JSON.parse(stored),Object.keys(cardById)):freshState();}catch(err){state=freshState();storageOk=false;}
let audioFiles={},audioManifest, activeButton=null, feedback=null, route='', levelFilter='all', signal='statement', catalogQuery='', catalogFilter='all', catalogLevel='all', flashIndex=0, flashDirection='ru', mistakeTab='mine', currentAudio=new Audio(), toastTimer, audioRequest=0;
const audioReady=fetch('./audio-manifest.json').then(r=>{if(!r.ok)throw Error('Audio not ready');return r.json()}).then(m=>{audioManifest=m;audioFiles=m.files;return m}).catch(()=>null);
currentAudio.preload='none';
function stopAudio(){audioRequest++;currentAudio.pause();currentAudio.currentTime=0;activeButton?.classList.remove('playing');activeButton?.setAttribute('aria-pressed','false');activeButton=null;}
currentAudio.addEventListener('ended',stopAudio);
currentAudio.addEventListener('error',()=>{if(activeButton){stopAudio();toast('Не удалось загрузить запись. Подключитесь к интернету или сохраните аудио для офлайн-занятий.');}});
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageOk=true;}catch(err){storageOk=false;toast('Не удалось сохранить прогресс. Сделайте резервную копию в настройках.');} }
function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,6500);}
function applySettings(){document.documentElement.style.fontSize=state.settings.font+'px';currentAudio.playbackRate=state.settings.rate;}
applySettings();
$('.topbar [data-action=settings]').innerHTML=icon('settings');
$('.bottom-nav').innerHTML=[['today','Сегодня'],['map','Понять'],['practice','Практика'],['mistakes','Ошибки']].map(([id,title])=>`<a href="#${id}">${icon(id)}<span>${title}</span></a>`).join('');
function audio(text,label='Послушать фразу'){return `<button type="button" class="audio-btn" data-action="audio" data-text="${e(text)}" aria-label="${e(label)} — Microsoft Ryan" aria-pressed="false">${icon('audio')}</button>`;}
function heading(kicker,title,extra=''){return `<div class="page-heading"><div><p class="eyebrow">${e(kicker)}</p><h1>${e(title)}</h1></div>${extra}</div>`;}
function stats(){const day=state.days[localDay()]||{ids:[]};return `<div class="stats"><div class="stat"><strong>${day.ids.length}<small style="display:inline;font-size:.9rem"> / ${state.settings.goal}</small></strong><small>карточек сегодня</small></div><div class="stat"><strong>${Object.keys(state.cards).length}</strong><small>из ${C.cards.length} в работе</small></div><div class="stat"><strong>${dueCards(C.cards,state).length}</strong><small>пора повторить</small></div></div>`;}
function week(){const today=new Date();return `<div class="week">${Array.from({length:7},(_,i)=>{const d=new Date(today);d.setDate(d.getDate()-6+i);const studied=(state.days[localDay(d.getTime())]?.ids?.length||0)>0;return `<div class="day ${studied?'done':''}" aria-label="${d.toLocaleDateString('ru-RU')}: ${studied?'занимались':'нет занятий'}"><span>${studied?'✓':d.getDate()}</span><small>${d.toLocaleDateString('ru-RU',{weekday:'short'})}</small></div>`}).join('')}</div>`;}
function lessonRow(l){const studied=C.cards.filter(c=>c.lesson===l.id&&state.cards[c.id]).length;return `<a class="lesson-row" href="#lesson/${l.id}"><span class="lesson-number">${String(l.index+1).padStart(2,'0')}</span><div><strong>${e(l.name)}</strong><small>${e(l.tag)}</small></div><span class="pill ${studied?'':'quiet'}">${studied?studied+'/10':l.level}</span></a>`;}
function renderToday(){
 const due=dueCards(C.cards,state).length,queue=buildQueue(C.cards,state,{limit:state.settings.goal});
 const next=queue.length?lessonById[cardById[queue.find(id=>!state.cards[id])||queue[0]].lesson]:C.lessons.at(-1);
 const hasSession=state.session&&state.session.index<state.session.queue.length;
 const remaining=hasSession?state.session.queue.length-state.session.index:queue.length;
 app.innerHTML=heading('КОСВЕННАЯ РЕЧЬ · B1 → B2','Понять.\nПересказать. Запомнить.')+`<div class="today-grid"><div><section class="daily-card"><div><div class="row"><span class="pill">${hasSession?'Занятие сохранено':due?`${due} к повторению`:'ВАШ СЛЕДУЮЩИЙ ШАГ'}</span><span class="session-count">${remaining||'✓'}</span></div><h2>${hasSession?'Продолжим с того же места.':due?'Вспомним знакомое.':e(next.name)}</h2><p>${hasSession?'Ваши ответы и очередь сохранены.':due?'Повторения первыми. Новое — небольшими шагами.':e(next.idea)}</p><button class="primary full" data-action="${hasSession?'resume':'start'}" data-mode="${queue.length?'daily':'mixed'}">${hasSession?'Продолжить':queue.length?`Начать · ${queue.length} ${plural(queue.length,'задание','задания','заданий')}`:'Повторить вперемешку'} <span aria-hidden="true">↗</span></button><a class="read-first" href="#lesson/${next.id}">${icon('book')} Сначала понять правило</a></div></section>${stats()}</div><aside class="meaning-panel"><div class="section-heading"><h2>Три способа пересказать</h2></div><p class="compact-note">Что сказали? Что спросили? О чём попросили?</p><div class="signal-tabs" role="group" aria-label="Утверждения, вопросы и просьбы">${C.signals.slice(0,3).map(x=>`<button data-action="signal" data-signal="${x.key}" class="${x.key===signal?'active ':''}signal-${x.key}" aria-pressed="${x.key===signal}">${x.label}<small>${x.title}</small></button>`).join('')}</div><div id="signal-detail">${signalDetail()}</div><a class="guide-link" href="#guide">Как строить косвенную речь <span aria-hidden="true">↗</span></a></aside></div><div class="section-heading"><h2>Ваш маршрут</h2><a href="#map" class="subtle-btn">${C.lessons.length} тем →</a></div><div class="lesson-list">${C.lessons.slice(next.index,Math.min(C.lessons.length,next.index+3)).map(lessonRow).join('')}</div><a class="catalog-link panel spacer" href="#catalog"><span>${icon("book")}<strong>Справочник по косвенной речи</strong><small>Правило, модель и примеры — с поиском</small></span><span aria-hidden="true">↗</span></a><a class="guide-link" href="#vocab"><span>Карточки: пересказать пять фраз</span><span aria-hidden="true">↗</span></a><div class="section-heading"><h2>Возвращаться понемногу</h2><span class="compact-note">7 дней</span></div><div class="panel week-panel">${week()}<p class="compact-note spacer">${Object.keys(state.cards).length?'Следующие повторения зависят от ваших ответов.':'Первые отметки появятся после ваших ответов.'}</p></div>`;
 if(!storageOk)app.insertAdjacentHTML('afterbegin','<div class="callout" role="alert">Не удалось прочитать сохранение. Проверьте доступ к хранилищу браузера и сохраните резервную копию в настройках.</div>');
}
function signalDetail(){const x=C.signals.find(x=>x.key===signal)||C.signals[0];return `<div class="row"><p class="signal-phrase signal-${x.key}" lang="en">${e(x.en)}</p>${audio(x.en)}</div><p>${e(x.ru)}</p><small>Сначала определите тип фразы. Потом — кто говорит, когда и где.</small>`;}
function plural(n,one,few,many){return n%10===1&&n%100!==11?one:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?few:many;}
function renderMap(){
 const groups=[['b1','01—06 · B1','Основа: кто и что сказал'],['bridge','07—10 · B1+','Вопросы, время и планы'],['b2','11—16 · B2','Контекст и точный пересказ']];
 app.innerHTML=heading('ПО ОДНОМУ ШАГУ','Понять косвенную речь')+`<p class="intro">${C.lessons.length} коротких тем. В каждой — одна главная мысль, десять пар «прямая → косвенная» с Ryan и десять заданий.</p><a class="guide-link panel" href="#guide"><span>${icon('map')} Четыре шага понятного пересказа</span><span aria-hidden="true">↗</span></a><div class="segmented spacer" aria-label="Уровень">${[['all','Весь путь'],['b1','B1'],['bridge','B1+'],['b2','B2']].map(([id,t])=>`<button data-action="filter" data-level="${id}" class="${levelFilter===id?'active':''}" aria-pressed="${levelFilter===id}">${t}</button>`).join('')}</div>`+groups.filter(([id])=>levelFilter==='all'||levelFilter===id).map(([id,kicker,title])=>`<section><div class="section-heading"><div><p class="eyebrow">${kicker}</p><h2>${title}</h2></div></div><div class="lesson-list">${C.lessons.filter(l=>l.group===id).map(lessonRow).join('')}</div></section>`).join('')+`<a class="catalog-link panel spacer" href="#catalog"><span><strong>Найти нужное правило</strong><small>Say / tell, вопросы, просьбы, времена, контекст</small></span><span aria-hidden="true">↗</span></a><div class="section-heading"><h2>Опоры для памяти</h2></div><div class="quick-links"><a class="panel" href="#compare"><strong>Почувствовать разницу ↗</strong><small>${C.contrasts.length} пар: похожая фраза — другой пересказ</small></a><a class="panel" href="#vocab"><strong>Карточки для памяти ↗</strong><small>${C.cards.length} примеров · сначала ваша попытка</small></a></div>`;
}
function renderGuide(){
 const first=C.lessons[0].id;
 app.innerHTML=`<a href="#map" class="back-link">${icon('back')} К темам</a>`+heading('НЕ ДОСЛОВНО, А ПО СМЫСЛУ','Четыре шага')+`<div class="stack"><section class="panel"><span class="pill">01 · Тип фразы</span><h2 class="spacer">Что человек сделал словами?</h2><p>Сообщил факт → said / told + предложение. Спросил → asked + if / whether или вопросительное слово. Попросил → asked someone to do; велел → told someone to do.</p><div class="forms spacer"><div class="form-row"><span class="en" lang="en">She said she was busy.</span><span>Передаём сообщение.</span></div><div class="form-row"><span class="en" lang="en">She asked if I was busy.</span><span>Передаём вопрос, порядок слов обычный.</span></div><div class="form-row"><span class="en" lang="en">She asked me to wait.</span><span>Передаём просьбу: кому + to + действие.</span></div></div></section><section class="panel"><span class="pill">02 · Люди</span><h2 class="spacer">Кто такие I, you и we?</h2><p>Местоимения выбираются по смыслу. I становится he / she, если пересказывает другой человек; если пересказываю свои слова, I остаётся I. You может стать me, us, him или her — смотрите, кому говорили.</p><p class="memory-hook">Не меняйте I → he автоматически. Сначала назовите человека.</p></section><section class="panel"><span class="pill">03 · Время глагола</span><h2 class="spacer">Переносим точку зрения.</h2><p>После said / told / asked часто сдвигаем время назад. Это удобная модель пересказа прошлого. Если сообщение всё ещё верно или актуально, исходное время тоже может сохраняться.</p><div class="forms spacer">${[['work → worked','Present Simple → Past Simple'],['am working → was working','Present Continuous → Past Continuous'],['have finished → had finished','Present Perfect → Past Perfect'],['worked → had worked','Past Simple → Past Perfect; иногда worked тоже допустимо'],['will → would · can → could','Будущее и возможность в прошлом'],['had done → had done','Past Perfect уже не сдвигается']].map(([en,ru])=>`<div class="form-row"><span class="en" lang="en">${en}</span><span>${ru}</span></div>`).join('')}</div><p class="compact-note spacer">Should, could, would и might обычно не меняются. Время — часть смысла, а не обязательная механическая замена.</p></section><section class="panel"><span class="pill">04 · Сейчас и здесь</span><h2 class="spacer">Сверяем ситуацию.</h2><p>Tomorrow → the next day, here → there, this → that нужны, когда меняется день, место или точка отсчёта. При пересказе в тот же день и в том же месте слова могут остаться прежними.</p><p class="memory-hook">Кто? Кому? Когда? Где? Эти четыре вопроса объясняют почти все замены.</p></section></div><div class="section-heading"><h2>Закрепить без зубрёжки</h2></div><div class="panel"><p>Прочитайте короткое правило. Посмотрите на исходную фразу и перескажите её до раскрытия. Сравните с образцом, послушайте Ryan и придумайте свой пример.</p><p>Пройдите десять заданий. Ошибка вернётся через несколько карточек; следующие занятия будут начинаться с повторений, срок которых уже подошёл.</p><div class="stack spacer"><a class="link-button" href="#lesson/${first}">Начать с первого шага →</a><a class="link-button" href="#vocab">Пересказать пять фраз →</a><a class="link-button" href="#practice">Перейти к тренировке →</a></div></div>`;
}
function typeLabel(p){return {statement:'Утверждения',question:'Вопросы',request:'Просьбы',context:'Контекст',reporting:'Глаголы пересказа'}[p.type]||'Правило';}
function placementText(){return 'Смотрите на ситуацию и передавайте смысл. Варианты с тем же смыслом указаны в разборе.';}
function renderCatalog(){
 app.innerHTML=`<a href="#map" class="back-link">${icon('back')} К темам</a>`+heading('16 ПРАВИЛ · С ПОИСКОМ','Найти и вспомнить')+`<p class="intro">Короткие правила с примерами «прямая → косвенная». Раскройте тему: подсказка для памяти, объяснение и голос Ryan.</p><label class="search-label" for="catalog-search">Модель на английском или правило по-русски</label><input id="catalog-search" class="answer-input catalog-search" type="search" placeholder="Например: asked, вопросы, местоимения" value="${e(catalogQuery)}" autocomplete="off" autocorrect="off" spellcheck="false"><div class="catalog-filters" role="group" aria-label="Тип правила">${[['all','Все · 16'],['statement','Утверждения'],['question','Вопросы'],['request','Просьбы'],['context','Контекст'],['reporting','Глаголы пересказа']].map(([key,label])=>`<button data-action="catalog-filter" data-filter="${key}" class="${catalogFilter===key?'active':''}" aria-pressed="${catalogFilter===key}">${label}</button>`).join('')}</div><div class="row catalog-level"><label for="catalog-level">Этап курса</label><select id="catalog-level">${[['all','Весь путь'],['B1','B1'],['B1+','B1+'],['B2','B2']].map(([v,t])=>`<option value="${v}" ${catalogLevel===v?'selected':''}>${t}</option>`).join('')}</select></div><p id="catalog-count" class="compact-note" role="status"></p><div id="catalog-results"></div>`;
 updateCatalog();
}
function updateCatalog(){
 const norm=x=>x.toLowerCase().replace(/ё/g,'е');const q=norm(catalogQuery.trim());
 const found=C.patterns.filter(p=>(catalogFilter==='all'||p.type===catalogFilter)&&(catalogLevel==='all'||p.level===catalogLevel)&&norm([p.model,p.ru,p.note,p.hook,p.why,lessonById[p.lesson].name,...p.cardIds.flatMap(id=>[cardById[id].full,cardById[id].direct])].join(' ')).includes(q));
 $('#catalog-count').textContent=`Найдено: ${found.length} из ${C.patterns.length}`;
 $('#catalog-results').innerHTML=found.length?found.map(p=>`<details class="pattern-entry"><summary><span><span class="entry-number">${String(p.number).padStart(2,'0')} · ${typeLabel(p)}</span><strong lang="en">${e(p.model)}</strong><small>${e(p.ru)}</small></span><span class="pill quiet">${p.level}</span></summary><div><div class="row"><span class="label">СЛУШАТЬ ПРИМЕР</span>${audio(cardById[p.cardIds[0]].full,'Послушать пример')}</div><div class="memory-hook"><span class="label">ДЛЯ ПАМЯТИ</span><p>${e(p.hook)}</p></div><p>${e(p.why)}</p><p class="compact-note spacer">${e(placementText(p))}</p>${p.note?`<p class="compact-note spacer">${e(p.note)}</p>`:''}${p.cardIds.map(id=>{const c=cardById[id];return `<article class="catalog-example"><p class="example-context">${e(c.context)}</p><div class="inline-audio"><p class="en blue" lang="en">“${e(c.direct)}”</p>${audio(c.direct)}</div><span class="label reported-arrow" aria-hidden="true">↓ ПЕРЕСКАЗ</span><div class="inline-audio"><p class="en" lang="en">${e(c.full)}</p>${audio(c.full)}</div><p>${e(c.ru)}</p></article>`;}).join('')}<div class="stack spacer"><button data-action="start" data-mode="lesson" data-lesson="${p.lesson}">Тренировать тему · 10 заданий</button><a class="subtle-btn" href="#lesson/${p.lesson}">Разобрать тему: ${e(lessonById[p.lesson].name)} →</a></div></div></details>`).join(''):`<div class="empty-state spacer"><h2>Совпадений пока нет.</h2><p>Попробуйте начальную форму, русский смысл или другой фильтр.</p><button data-action="catalog-reset">Показать все 16</button></div>`;
}
function renderLesson(id){
 const l=lessonById[id];if(!l){go('map');return;}const cards=C.cards.filter(c=>c.lesson===id);state.lessons[id]=true;save();
 app.innerHTML=`<a href="#map" class="back-link">${icon('back')} Понять косвенную речь</a>`+heading(`${l.level} · ШАГ ${l.index+1} ИЗ ${C.lessons.length}`,l.name)+`<div class="lesson-layout"><div><section class="rule-card"><span class="eyebrow">ОДНА ГЛАВНАЯ МЫСЛЬ</span><h2>${e(l.idea)}</h2><p>${e(l.rule[0])}</p></section><ul class="rule-points">${l.rule.slice(1).map(r=>`<li>${e(r)}</li>`).join('')}</ul><div class="section-heading"><h2>Удержать в памяти</h2></div><div class="forms">${l.forms.map(([en,ru])=>`<div class="form-row"><span lang="en" class="en">${e(en)}</span><span>${e(ru)}</span></div>`).join('')}</div><div class="callout">${e(l.recall)}</div><button class="primary full spacer" data-action="start" data-mode="lesson" data-lesson="${id}">Закрепить · 10 заданий</button><div class="section-heading"><h2>10 примеров в контексте</h2><span class="compact-note">Ryan · UK</span></div><p class="compact-note">Прочитайте исходные слова. Попробуйте пересказать их сами, затем откройте образец.</p>${cards.map((c,i)=>`<article class="example"><span class="example-number">${String(i+1).padStart(2,'0')}</span><p class="example-context">${e(c.context)}</p><div class="english-line"><p class="en direct-quote" lang="en">“${e(c.direct)}”</p>${audio(c.direct,'Послушать исходную фразу')}</div><details class="example-explanation"><summary>Косвенная речь и объяснение</summary><div><div class="english-line"><p class="en reported-line" lang="en">${e(c.full)}</p>${audio(c.full,'Послушать косвенную речь')}</div><p>${e(c.ru)}</p><p class="muted">${e(c.why)}</p>${c.fullAlternatives.length?`<p class="compact-note spacer">Также верно: <span lang="en">${e(c.fullAlternatives.join(' / '))}</span></p>`:''}</div></details></article>`).join('')}</div><aside class="lesson-aside"><div class="panel"><span class="label copper">ДЛЯ ПАМЯТИ</span><h2 class="spacer">Объясните свой выбор.</h2><p class="muted">Почему меняется время, порядок слов или местоимение? Понимание делает пересказ свободнее.</p><button class="full spacer" data-action="start" data-mode="why" data-lesson="${id}">Почему так?</button></div><details open><summary>Ловушка русскоговорящих</summary><div><p class="compact-note spacer">Нужный смысл: ${e(l.trapRu)}</p><p class="en wrong spacer" lang="en">${e(l.bad)}</p><p class="en right" lang="en">${e(l.good)}</p><p class="spacer">${e(l.trap)}</p><div class="spacer">${audio(l.good)}</div></div></details><div class="recall-box"><span class="label copper">ПЕРЕСКАЖИТЕ ИЗ ПАМЯТИ</span><p>${e(cards[4].context)}</p><p class="en spacer" lang="en">“${e(cards[4].direct)}”</p><button class="spacer" data-action="reveal" aria-expanded="false" aria-controls="lesson-answer">Показать ответ</button><div id="lesson-answer" hidden><p class="en spacer" lang="en">${e(cards[4].full)}</p>${audio(cards[4].full)}</div></div><div class="stack spacer"><button data-action="start" data-mode="recall" data-lesson="${id}">Пересказать самому</button><button data-action="start" data-mode="listen" data-lesson="${id}">Услышать с Ryan</button>${C.lessons[l.index+1]?`<a class="link-button" href="#lesson/${C.lessons[l.index+1].id}">Следующая тема →</a>`:''}</div></aside></div>`;
}
function renderCompare(){app.innerHTML=`<a href="#map" class="back-link">${icon('back')} К темам</a>`+heading('ПОХОЖИЕ ФРАЗЫ · РАЗНЫЙ ПЕРЕСКАЗ','Почувствуйте разницу')+C.contrasts.map(c=>`<section><div class="section-heading"><h2>${e(c.title)}</h2></div><div class="contrast-grid">${[[c.a,c.ar],[c.b,c.br]].map(([t,r])=>`<article class="panel"><p class="en" lang="en">${e(t)}</p><p>${e(r)}</p><div class="spacer">${audio(t)}</div></article>`).join('')}</div><p class="compact-note spacer">${e(c.note)}</p></section>`).join('')+`<button class="primary spacer" data-action="start" data-mode="lesson" data-lesson="${C.lessons[0].id}">Закрепить в контексте</button>`;}
function renderVocab(){
 const pages=Math.ceil(C.cards.length/5),items=C.cards.slice(flashIndex*5,flashIndex*5+5);
 app.innerHTML=`<a href="#map" class="back-link">${icon('back')} К темам</a>`+heading('КАРТОЧКИ ДЛЯ ПАМЯТИ','Сначала перескажите')+`<p class="intro">Пять фраз за раз. Перескажите вслух до раскрытия, затем сравните и послушайте Ryan. Обратное направление помогает понять исходный смысл.</p><div class="segmented flash-direction" role="group" aria-label="Направление вспоминания">${[['ru','Прямая → косвенная'],['en','Косвенная → исходный смысл']].map(([d,t])=>`<button data-action="flash-direction" data-direction="${d}" class="${flashDirection===d?'active':''}" aria-pressed="${flashDirection===d}">${t}</button>`).join('')}</div><div class="row flash-navigation"><button class="icon-btn" data-action="flash-page" data-step="-1" ${flashIndex===0?'disabled':''} aria-label="Предыдущие пять фраз">←</button><div><span class="eyebrow">${flashIndex*5+1}—${Math.min(C.cards.length,flashIndex*5+5)} ИЗ ${C.cards.length}</span><h2>${e(lessonById[items[0].lesson].name)}</h2></div><button class="icon-btn" data-action="flash-page" data-step="1" ${flashIndex===pages-1?'disabled':''} aria-label="Следующие пять фраз">→</button></div><div class="flash-grid">${items.map((c,i)=>`<article class="panel flash-card"><span class="eyebrow">${String(flashIndex*5+i+1).padStart(2,'0')} · ${lessonById[c.lesson].level}</span><p class="example-context">${e(c.context)}</p><div class="inline-audio"><h2 class="spacer en" lang="en">${e(flashDirection==='ru'?c.direct:c.full)}</h2>${audio(flashDirection==='ru'?c.direct:c.full)}</div><button class="subtle-btn spacer" data-action="reveal" aria-expanded="false" aria-controls="flash-answer-${c.id}">Показать ответ</button><div id="flash-answer-${c.id}" class="flash-answer" hidden><div class="inline-audio"><p class="en" lang="en">${e(flashDirection==='ru'?c.full:c.direct)}</p>${audio(flashDirection==='ru'?c.full:c.direct)}</div><p>${e(c.ru)}</p><p class="memory-hook">${e(patternById[c.pattern].hook)}</p><p class="compact-note">${e(c.why)}</p>${flashDirection==='en'?'<p class="compact-note spacer">Это один возможный исходный вариант. Косвенный пересказ передаёт содержание, поэтому точную исходную цитату не всегда можно восстановить.</p>':''}</div></article>`).join('')}</div><button class="primary full spacer" data-action="start" data-mode="lesson" data-lesson="${items[0].lesson}">Закрепить тему · 10 заданий</button><a class="guide-link" href="#lesson/${items[0].lesson}">Разобрать правило и примеры →</a><button class="full spacer" data-action="flash-page" data-step="1" ${flashIndex===pages-1?'disabled':''}>Следующие пять →</button>`;
}
function renderPractice(){
 const due=dueCards(C.cards,state).length,mistakes=Object.values(state.mistakes).filter(m=>!m.resolved).length,ongoing=state.session&&state.session.index<state.session.queue.length;
 app.innerHTML=heading('ВСПОМНИТЬ. ОБЪЯСНИТЬ. ПОВТОРИТЬ.','Тренировка')+`<p class="intro">Ответьте до подсказки. После попытки — понятное объяснение, правильная фраза и голос Ryan.</p>${ongoing?`<div class="panel row spacer"><div><strong>Занятие сохранено</strong><small style="display:block">Осталось ${state.session.queue.length-state.session.index} заданий</small></div><button data-action="resume">Продолжить</button></div>`:''}<div class="practice-options spacer">${[['daily','today','На сегодня','Повторения и новые задания от B1 к B2.'],['mixed','map','Вперемешку','Выбрать, вписать, исправить, сказать. В основном по изученному.'],['why','book','Почему так?','Объясните изменение времени, местоимения или порядка слов.'],['recall','talk','Пересказать самому','Передайте чужие слова вслух, затем сравните и оцените себя.'],['listen','audio','Услышать с Ryan','Слушайте готовый пересказ и восстанавливайте пропущенные слова.'],['mistakes','mistakes','Мои трудные места',mistakes?`${mistakes} ${plural(mistakes,'карточка','карточки','карточек')} из ваших ошибок.`:'Здесь появятся задания, которые требуют внимания.'],['due','today','Пора повторить',due?`${due} ${plural(due,'карточка ждёт','карточки ждут','карточек ждут')} повторения.`:'Срок повторения ещё не подошёл.']].map(([mode,ico,title,desc])=>`<button class="mode-card ${mode==='daily'?'mode-main':''}" data-action="start" data-mode="${mode}" ${mode==='due'&&!due||mode==='mistakes'&&!mistakes?'disabled':''}>${icon(ico)}<strong>${title}</strong><small>${desc}</small></button>`).join('')}</div><div class="section-heading"><h2>Как материал остаётся в памяти</h2></div><div class="panel"><p>Ошибка возвращается через несколько заданий. Уверенные ответы постепенно увеличивают интервал до следующей встречи.</p><div class="chip-row"><span class="key-chip">1 день</span><span class="key-chip">3 дня</span><span class="key-chip">7 дней</span><span class="key-chip">14 дней</span><span class="key-chip">30+ дней</span></div><p class="compact-note spacer">Повторения подстраиваются под ответы. Уже сегодня можно потренироваться ещё, но это не увеличит интервал искусственно. Новые темы добавляются в режиме «На сегодня»; любую тему также можно открыть вручную.</p></div>`;
}
function renderMistakes(){const mistakes=C.cards.filter(c=>state.mistakes[c.id]&&!state.mistakes[c.id].resolved).sort((a,b)=>state.mistakes[b.id].last-state.mistakes[a.id].last);app.innerHTML=heading('ПОНЯТЬ И ИСПРАВИТЬ','Ошибки без спешки')+`<div class="segmented"><button class="${mistakeTab==='mine'?'active':''}" aria-pressed="${mistakeTab==='mine'}" data-action="mistake-tab" data-tab="mine">Мои ошибки · ${mistakes.length}</button><button class="${mistakeTab==='traps'?'active':''}" aria-pressed="${mistakeTab==='traps'}" data-action="mistake-tab" data-tab="traps">Русские ловушки</button></div>`+(mistakeTab==='mine'?(mistakes.length?`<p class="intro spacer">Карточка покинет этот список после правильных ответов в два разных дня после ошибки.</p><button class="primary" data-action="start" data-mode="mistakes">Повторить трудные места</button><div class="spacer">${mistakes.map(c=>`<article class="error-card"><div class="row"><a class="label copper" href="#lesson/${c.lesson}">${e(lessonById[c.lesson].name)}</a><span class="count-badge">${state.mistakes[c.id].count} ${plural(state.mistakes[c.id].count,'ошибка','ошибки','ошибок')}</span></div><p>${e(c.ru)}</p><details><summary>Правильный вариант и объяснение</summary><div><div class="inline-audio"><p class="en" lang="en">${e(c.full)}</p>${audio(c.full)}</div><p>${e(c.why)}</p>${state.mistakes[c.id].lastAnswer?`<p class="compact-note">Ваша попытка: ${e(state.mistakes[c.id].lastAnswer)}</p>`:''}</div></details><small>Повторение: ${formatDue(state.cards[c.id]?.due)}</small></article>`).join('')}</div>`:`<div class="empty-state spacer"><span class="copper">${icon('check')}</span><h2>Пока всё чисто</h2><p>Ошибки из тренировок сохранятся здесь с объяснением. А типичные русские ловушки можно посмотреть уже сейчас.</p><button data-action="mistake-tab" data-tab="traps">Посмотреть ловушки</button></div>`):`<div class="spacer">${C.traps.map(t=>`<details><summary>${e(t.title)}</summary><div><p class="compact-note spacer">Нужный смысл: ${e(t.ru)}</p><p class="en wrong spacer" lang="en">${e(t.bad)}</p><div class="inline-audio"><p class="en right" lang="en">${e(t.good)}</p>${audio(t.good)}</div><p class="spacer">${e(t.why)}</p><a class="subtle-btn link-button spacer" href="#lesson/${t.id}">Разобрать правило</a></div></details>`).join('')}</div>`);}
function formatDue(due){if(!due)return 'после первого ответа';if(due<=Date.now())return 'сейчас';if(localDay(due)===localDay())return new Date(due).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})+' сегодня';return new Date(due).toLocaleDateString('ru-RU',{day:'numeric',month:'long'});}
function start(mode,lesson){if(state.session&&state.session.index<state.session.queue.length){openSessionChoice(mode,lesson);return;}startNow(mode,lesson);}
function startNow(mode,lesson){let queue=buildQueue(C.cards,state,{mode,lesson,limit:lesson?10:state.settings.goal});if(!queue.length){toast(mode==='due'?'Сейчас нет карточек к повторению. Можно выбрать практику вперемешку.':mode==='mistakes'?'Новых ошибок нет.':'Все новые карточки уже изучены. Выберите практику вперемешку.');return;}state.session={mode,lesson:lesson||null,queue,index:0,initial:queue.length,results:[],retries:{},failed:[],started:Date.now()};feedback=null;save();go('session');}
function openSessionChoice(mode,lesson){$('#settings-body').innerHTML=`<div class="settings-header"><h2>Продолжить занятие?</h2><button class="icon-btn" data-action="close" aria-label="Закрыть">${icon('close')}</button></div><p class="intro spacer">У вас сохранена очередь. Можно вернуться к ней или начать новую. Все уже оценённые ответы сохранятся.</p><div class="stack"><button class="primary" data-action="resume">Продолжить сохранённое</button><button data-action="replace-session" data-mode="${e(mode)}" data-lesson="${e(lesson||'')}">Начать выбранную тренировку</button></div>`;dialog.showModal();}
function go(hash){if(location.hash==='#'+hash){render();}else location.hash=hash;}
function activeCard(){return state.session?cardById[state.session.queue[state.session.index]]:null;}
function exerciseKind(c){return ['recall','listen','why'].includes(state.session.mode)?state.session.mode:c.kind;}
function renderSession(){
 const s=state.session;if(!s){go('practice');return;}if(s.index>=s.queue.length){renderSummary();return;}
 const c=activeCard(),l=lessonById[c.lesson],kind=exerciseKind(c),isRetry=s.failed.includes(c.id);
 const labels={choice:'Выберите верный пересказ',gap:'Вспомните без вариантов',fix:'Исправьте косвенную речь',recall:'Перескажите по-английски',listen:'Услышьте пересказ',why:'Почему здесь именно так?'};
 let question=`<p class="context">${e(c.context)}</p>`,controls='',note='';
 if(kind!=='listen')question+=`<div class="source-quote"><span class="label">ИСХОДНЫЕ СЛОВА</span><div class="inline-audio"><p class="en" lang="en">“${e(c.direct)}”</p>${audio(c.direct,'Послушать исходную фразу')}</div></div>`;
 if(kind==='recall'){
  controls='<p class="compact-note spacer">Произнесите пересказ вслух до раскрытия. Затем сравните с образцом и оцените себя.</p><button class="primary full spacer" data-action="show-answer">Сказал — сравнить с образцом</button>';
 }else if(kind==='why'){
  question+=`<p class="question" lang="en">${e(c.full)}</p>`;controls=choices(shuffled(c.meaningOptions),'reasons');
 }else{
  question+=`<p class="question" lang="en">${kind==='fix'?e(c.incorrect):e(c.prompt).replace('___','<span class="blank" aria-label="пропуск">…</span>')}</p>`;
  if(kind==='listen'){question+=`<div class="listen-row">${audio(c.full,'Послушать задание')}<p>Послушайте Ryan.<br><span class="compact-note">Какие слова звучат в пропуске?</span></p></div>`;controls=choices(shuffled(c.options));}
  else if(kind==='choice')controls=choices(shuffled(c.options));
  else {controls=`<form class="answer-form" id="answer-form"><label for="answer-input">${kind==='fix'?'Исправленное предложение целиком':'Пропущенные слова'}</label><input id="answer-input" class="answer-input" aria-label="Ваш ответ на английском" autocomplete="off" autocorrect="off" autocapitalize="none" spellcheck="false" lang="en" required><div class="input-actions"><button type="submit" class="primary">Проверить</button></div></form><button class="subtle-btn spacer" data-action="show-answer">Не помню — разобрать</button>`;note=kind==='fix'?'Исправьте предложение, сохраняя смысл и остальные слова. Сокращения, регистр и конечная пунктуация не мешают проверке.':'Впишите только пропущенные слова. Учитывайте ситуацию над цитатой; допустимые варианты будут показаны в разборе.';}
 }
 app.innerHTML=`<section class="exercise"><div class="session-top"><a href="#practice" class="back-link" style="margin:0">${icon('back')} Пауза</a><span class="compact-note">${s.index+1} / ${s.queue.length}${isRetry?' · повтор':''}</span></div><div class="session-progress" role="progressbar" aria-label="Занятие" aria-valuemin="0" aria-valuemax="${s.queue.length}" aria-valuenow="${s.index}"><div style="width:${s.index/s.queue.length*100}%"></div></div><p class="eyebrow">${kind==='listen'?'LISTENING · RYAN':`${l.level} · ${e(l.name)}`}</p><h1 class="exercise-title">${labels[kind]}</h1><div class="question-area">${question}</div><div id="exercise-controls">${controls}</div><div id="feedback"></div>${note?`<p class="question-note">${note}</p>`:''}</section>`;
 if(feedback?.id===c.id)showFeedback(feedback);
}
function reasonDistractors(c){return c.meaningOptions.filter(x=>x!==c.meaning);}
function choices(options,kind='words'){return `<div class="choices ${kind==='reasons'?'reason-choices':'form-choices'}">${options.map(a=>`<button class="choice" data-action="answer" data-value="${e(a)}"><span ${kind!=='reasons'?'lang="en"':''}>${e(a)}</span></button>`).join('')}</div>`;}
function submitAnswer(value){if(feedback)return;const c=activeCard(),kind=exerciseKind(c);const correct=checkAnswer(c,value,kind);feedback={id:c.id,correct,answer:value,revealed:false};showFeedback(feedback);}
function revealAnswer(){if(feedback)return;const c=activeCard(),recall=exerciseKind(c)==='recall';feedback={id:c.id,correct:recall?null:false,answer:'',revealed:true};showFeedback(feedback);}
function intervalLabel(days){return days<1?'через 10 мин':days===1?'завтра':`через ${days} дн.`;}
function reviewLabel(c,r,recovery){const p=planReview(state.cards[c.id],r,Date.now(),recovery);const remaining=(p.due-Date.now())/DAY;return remaining<.1?'сегодня':remaining<1.05?'завтра':`через ${Math.ceil(remaining)} дн.`;}
function showFeedback(f){const c=activeCard(),s=state.session;if(!c)return;$('#exercise-controls').querySelectorAll('button,input').forEach(el=>el.disabled=true);
 if(!f.revealed){$('#exercise-controls').querySelectorAll('.choice').forEach(el=>{const correct=checkAnswer(c,el.dataset.value,exerciseKind(c));if(correct)el.classList.add('correct');else if(el.dataset.value===f.answer)el.classList.add('incorrect');});}
 const recovery=s.failed.includes(c.id);const ratings=f.correct===false?['again']:f.correct===null?['again','hard','good']:['hard','good','easy'];
 $('#feedback').innerHTML=`<div class="feedback ${f.correct===false?'bad':f.correct===null?'neutral':''}" role="status"><h3>${f.correct===true?'Верно':f.correct===false?'Разберём и повторим':'Сравните со своим ответом'}</h3><div class="inline-audio"><p class="en" lang="en">${e(c.full)}</p>${audio(c.full)}</div><p>${e(c.ru)}</p><p class="pattern-answer en" lang="en">${e(patternById[c.pattern].model)}</p><p class="compact-note">${e(c.why)}</p><p class="memory-hook">${e(patternById[c.pattern].hook)}</p>${c.fullAlternatives.length?`<p class="compact-note">Также верно: <span lang="en">${e(c.fullAlternatives.join(" / "))}</span></p>`:""}${f.correct===null?'<p class="compact-note">Другой естественный перевод тоже возможен. Оцените, восстановили ли вы нужную модель и смысл.</p>':''}<div class="${ratings.length===1?'spacer':'grade-buttons'}">${ratings.map(r=>`<button class="${ratings.length===1?'primary full':''}" data-action="grade" data-grade="${r}">${{again:f.correct===false?'Продолжить':'Не вспомнил',hard:'С трудом',good:'Помню',easy:'Легко'}[r]}<small>${r==='again'?(s.retries[c.id]?'Через 10 минут':'Ещё раз в этом занятии'):reviewLabel(c,r,recovery)}</small></button>`).join('')}</div></div>`;
 $('#feedback .feedback').scrollIntoView({block:'end',behavior:'smooth'});
}
function grade(rating){const c=activeCard(),s=state.session;if(!c||!feedback)return;const wrong=feedback.correct===false||rating==='again';if(wrong)rating='again';const recovery=s.failed.includes(c.id);applyGrade(state,c,rating,{recovery,wrong,answer:feedback.answer});s.results.push({id:c.id,rating,correct:!wrong,retry:recovery});
 if(wrong){if(!s.failed.includes(c.id))s.failed.push(c.id);if(!s.retries[c.id]){s.retries[c.id]=1;s.queue.splice(Math.min(s.index+4,s.queue.length),0,c.id);}}
 s.index++;feedback=null;save();stopAudio();renderSession();window.scrollTo(0,0);
}
function renderSummary(){const s=state.session;if(!s){go('today');return;}const first=s.results.filter(r=>!r.retry),correct=first.filter(r=>r.correct).length;const next=Object.values(state.cards).map(c=>c.due).sort((a,b)=>a-b)[0];app.innerHTML=`<section class="exercise"><div class="score-head"><p class="eyebrow">ЗАНЯТИЕ ЗАВЕРШЕНО</p><h1 class="spacer">Один шаг сделан.</h1><div class="summary-ring"><strong>${correct} / ${first.length}</strong><small>с первой попытки</small></div><p>${s.failed.length?`${s.failed.length} ${plural(s.failed.length,'трудная карточка сохранена','трудные карточки сохранены','трудных карточек сохранены')} для повторения.`:'Все ответы уверенные? Продолжим, когда подойдёт срок повторения.'}</p></div><div class="panel spacer"><div class="row"><span>Всего ответов</span><strong>${s.results.length}</strong></div><div class="row spacer"><span>Ближайшее повторение</span><strong>${formatDue(next)}</strong></div><p class="compact-note spacer">${storageOk?'Прогресс сохранён на этом устройстве.':'Прогресс не удалось сохранить. Экспортируйте копию в настройках.'}</p></div><button class="primary full spacer" data-action="finish">На сегодня готово</button><button class="subtle-btn full" data-action="finish-mistakes">Посмотреть трудные места</button></section>`;}
async function play(text,button){if(button===activeButton&&!currentAudio.paused){stopAudio();return;}stopAudio();const request=audioRequest;let file=audioFiles[text];if(!file){await audioReady;file=audioFiles[text];}if(request!==audioRequest)return;if(!file){toast('Для этой фразы запись недоступна. Голос устройства не подставляется вместо Ryan.');return;}currentAudio.src=new URL(file.src,location.href.split('#')[0]).href;currentAudio.playbackRate=state.settings.rate;activeButton=button;button.classList.add('playing');button.setAttribute('aria-pressed','true');try{await currentAudio.play();}catch(err){if(request!==audioRequest||err.name==='AbortError')return;stopAudio();toast('Не удалось воспроизвести запись. Нажмите ещё раз; для первой загрузки нужен интернет.');}}
function showSettings(){const standalone=window.matchMedia('(display-mode: standalone)').matches||navigator.standalone;
 $('#settings-body').innerHTML=`<div class="settings-header"><div><p class="eyebrow">ЛИЧНОЕ ПРОСТРАНСТВО</p><h2 style="margin-top:7px">Настройки</h2></div><button class="icon-btn" data-action="close" aria-label="Закрыть настройки">${icon('close')}</button></div><section class="settings-section"><h3>Microsoft Ryan · British English</h3><p>Одинаковые записи на iPhone и iPad. Фразы записаны в чуть более спокойном темпе.</p><div class="row spacer"><label class="setting-label" for="rate">Скорость</label><select id="rate" data-setting="rate">${[[.8,'0,8× · медленнее'],[1,'1× · обычная'],[1.15,'1,15× · быстрее']].map(([v,l])=>`<option value="${v}" ${state.settings.rate===v?'selected':''}>${l}</option>`).join('')}</select>${audio(C.cards[0].full,'Проверить голос')}</div></section><section class="settings-section"><div class="row"><label for="font">Размер текста</label><select id="font" data-setting="font">${[[18,'Крупный · 18'],[20,'Больше · 20'],[22,'Максимум · 22']].map(([v,l])=>`<option value="${v}" ${state.settings.font===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="row spacer"><label for="goal">Карточек за занятие</label><select id="goal" data-setting="goal">${[5,10,15].map(v=>`<option value="${v}" ${state.settings.goal===v?'selected':''}>${v}</option>`).join('')}</select></div></section><section class="settings-section"><h3>${standalone?'Приложение на главном экране':'На главный экран iPhone / iPad'}</h3>${standalone?'<p>Вы открыли Report как отдельное приложение.</p>':'<ol class="install-steps"><li>Откройте постоянную ссылку Report в Safari.</li><li>Нажмите «Поделиться».</li><li>Выберите «На экран “Домой”».</li><li>Если есть переключатель «Открывать как веб-приложение», включите его и нажмите «Добавить».</li></ol>'}</section><section class="settings-section"><h3>Учиться без интернета</h3><p>Сохраните весь комплект аудио заранее. При загрузке держите приложение открытым.</p><button class="full spacer" data-action="offline" id="offline-button">${icon('download')} Сохранить уроки и аудио</button><p id="offline-status" class="compact-note spacer" role="status"></p></section><section class="settings-section"><h3>Ваш прогресс</h3><p>Хранится в этом браузере на этом устройстве. iPhone и iPad автоматически не синхронизируются. Для переноса сохраните копию и откройте её на другом устройстве.</p><div class="stack spacer"><button data-action="export">Сохранить резервную копию</button><button data-action="import">Восстановить из файла</button><input type="file" id="import-file" accept="application/json,.json" hidden></div><p class="compact-note spacer">Очистка данных сайта удаляет локальный прогресс. На iOS начинайте занятия из установленной иконки — у Safari и приложения могут быть отдельные хранилища.</p></section><details><summary>Как устроены повторения</summary><div><p class="compact-note">Базовые интервалы: 1, 3, 7, 14, 30, 60, 120 и 180 дней. «Легко» пропускает одну ступень. «С трудом» сокращает интервал. Ошибка возвращается после нескольких других заданий, затем — через 10 минут; успешное исправление закрепляется на следующий день. Одна и та же ошибка повторяется в занятии не более одного раза.</p><p class="compact-note spacer">Два успешных ответа в разные дни после ошибки убирают карточку из списка трудных. Это прозрачная адаптация по ответам, без обещания индивидуально оптимальных интервалов.</p></div></details><details><summary>Материал и источники</summary><div class="source-links"><p class="compact-note">Постепенный курс косвенной речи по Cambridge и British Council. Уровень обозначает сложность шага. Все примеры и объяснения подготовлены для этого курса; контекст задаёт людей, время и место. При проверке принимаются указанные допустимые варианты, включая необязательное that и if / whether.</p>${C.sources.map(x=>`<a href="${e(x.url)}" target="_blank" rel="noopener">${e(x.title)}</a>`).join('')}<a target="_blank" rel="noopener" href="https://www.psychologicalscience.org/journals/psychological-science/j.1467-9280.2008.02209.x/">Cepeda et al.: исследование интервалов повторения</a><a target="_blank" rel="noopener" href="https://learn.microsoft.com/en-us/azure/ai-services/speech-service/language-support">Microsoft: голоса Speech</a><a target="_blank" rel="noopener" href="https://support.apple.com/en-lamr/guide/iphone/iphea86e5236/ios">Apple: приложение на экране «Домой»</a></div></details><p class="compact-note spacer">Report 1.0 · ${C.patterns.length} правил · ${C.cards.length} заданий · ${C.lessons.length} тем · без рекламы и аналитики</p>`;
 dialog.showModal();if('serviceWorker'in navigator&&window.isSecureContext){caches.open('report-audio-v1').then(async cache=>{const keys=await cache.keys();const el=$('#offline-status');if(el)el.textContent=keys.length?`На устройстве: ${keys.length} из ${Object.keys(audioFiles).length||'…'} записей.`:'Аудио ещё не сохранено целиком.';});}
}
async function saveOffline(){const el=$('#offline-status'),button=$('#offline-button');if(!('serviceWorker'in navigator)||!window.isSecureContext){el.textContent='Для сохранения офлайн откройте приложение по ссылке HTTPS.';return;}button.disabled=true;try{await audioReady;if(!Object.keys(audioFiles).length)throw Error('manifest');await navigator.serviceWorker.ready;const cache=await caches.open('report-audio-v1'),files=Object.values(audioFiles),errors=[];let loaded=0;for(const file of files){const url=new URL(file.src,location.href.split('#')[0]).href;try{let response=await cache.match(url);if(!response){response=await fetch(url);if(!response.ok||!response.headers.get('content-type')?.includes('audio'))throw Error('audio');await cache.put(url,response);}}catch(err){errors.push(file.src);}loaded++;el.textContent=`Сохранение: ${loaded} из ${files.length}…`;}
 if(errors.length)throw Error(`${errors.length} записей не загрузились`);const persisted=await navigator.storage?.persist?.().catch(()=>false);el.textContent=`Готово: ${files.length} записей сохранены. Уроки и тренировки доступны офлайн. iOS может освободить данные при нехватке места.`;button.textContent='Сохранено для офлайн-занятий';}catch(err){el.textContent='Загрузка не завершена. Подключитесь к сети и нажмите ещё раз — уже сохранённые записи останутся.';}finally{button.disabled=false;}}
function exportProgress(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`report-progress-${localDay()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),30000);toast('Резервная копия подготовлена. Сохраните файл в «Файлы».');}
async function importProgress(file){if(!file)return;if(file.size>2e6){toast('Файл слишком большой. Выберите резервную копию Report.');return;}try{const candidate=validateState(JSON.parse(await file.text()),Object.keys(cardById));$('#settings-body').innerHTML=`<h2>Восстановить прогресс?</h2><p class="intro spacer">В файле ${Object.keys(candidate.cards).length} карточек в работе. Текущий прогресс будет заменён. Сначала можно сохранить свою копию.</p><div class="stack"><button data-action="export">Сохранить текущую копию</button><button class="primary" id="confirm-import">Восстановить из этого файла</button><button data-action="close">Отмена</button></div>`;$('#confirm-import').onclick=()=>{state=candidate;feedback=null;applySettings();save();dialog.close();go('today');toast('Прогресс восстановлен из файла.');};}catch(err){toast('Не удалось прочитать резервную копию. Текущий прогресс сохранён.');}}
function render(){const hash=location.hash.slice(1)||'today';route=hash.split('/')[0];stopAudio();document.querySelectorAll('.bottom-nav a').forEach(a=>{const active=a.hash==='#'+(['lesson','compare','vocab','guide','catalog'].includes(route)?'map':route==='session'?'practice':route);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});({today:renderToday,map:renderMap,guide:renderGuide,catalog:renderCatalog,lesson:()=>renderLesson(hash.split('/')[1]),compare:renderCompare,vocab:renderVocab,practice:renderPractice,mistakes:renderMistakes,session:renderSession}[route]||renderToday)();window.scrollTo(0,0);}
document.addEventListener('input',event=>{if(event.target.id==='catalog-search'){catalogQuery=event.target.value;updateCatalog();}});
window.addEventListener('hashchange',()=>{render();app.focus({preventScroll:true});});
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;
 if(a==='settings')showSettings();else if(a==='close')dialog.close();else if(a==='audio')play(b.dataset.text,b);else if(a==='filter'){levelFilter=b.dataset.level;renderMap();}else if(a==='signal'){signal=b.dataset.signal;stopAudio();document.querySelectorAll('[data-action=signal]').forEach(x=>{x.classList.toggle('active',x.dataset.signal===signal);x.setAttribute('aria-pressed',x.dataset.signal===signal);});$('#signal-detail').innerHTML=signalDetail();}else if(a==='catalog-filter'){catalogFilter=b.dataset.filter;renderCatalog();}else if(a==='catalog-reset'){catalogQuery='';catalogFilter='all';catalogLevel='all';renderCatalog();}else if(a==='flash-page'){flashIndex=Math.max(0,Math.min(Math.ceil(C.cards.length/5)-1,flashIndex+Number(b.dataset.step)));stopAudio();renderVocab();window.scrollTo(0,0);}else if(a==='flash-direction'){flashDirection=b.dataset.direction;stopAudio();renderVocab();}else if(a==='zero')submitAnswer('Ø');else if(a==='mistake-tab'){mistakeTab=b.dataset.tab;renderMistakes();}else if(a==='start')start(b.dataset.mode,b.dataset.lesson);else if(a==='replace-session'){dialog.close();state.session=null;startNow(b.dataset.mode,b.dataset.lesson||undefined);}else if(a==='resume'){dialog.close();go('session');}else if(a==='answer')submitAnswer(b.dataset.value);else if(a==='show-answer')revealAnswer();else if(a==='grade')grade(b.dataset.grade);else if(a==='finish'||a==='finish-mistakes'){state.session=null;feedback=null;save();go(a==='finish'?'today':'mistakes');}else if(a==='reveal'){const target=document.getElementById(b.getAttribute('aria-controls'));target.hidden=!target.hidden;b.setAttribute('aria-expanded',String(!target.hidden));b.textContent=target.hidden?'Показать ответ':'Скрыть ответ';if(!target.hidden&&target.classList.contains('flash-answer'))requestAnimationFrame(()=>target.scrollIntoView({block:'nearest',behavior:'smooth'}));}else if(a==='export')exportProgress();else if(a==='import')$('#import-file').click();else if(a==='offline')saveOffline();
});
document.addEventListener('submit',event=>{if(event.target.id==='answer-form'){event.preventDefault();const input=$('#answer-input').value.trim();if(input)submitAnswer(input);}});
document.addEventListener('change',event=>{const field=event.target;if(field.dataset.setting){state.settings[field.dataset.setting]=Number(field.value);applySettings();save();}if(field.id==='catalog-level'){catalogLevel=field.value;updateCatalog();}if(field.id==='import-file')importProgress(field.files[0]);});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAudio();});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
window.addEventListener('storage',event=>{if(event.key===STORAGE_KEY){toast('Прогресс изменился в другой вкладке. Обновите страницу перед следующим занятием.');}});
